function fewestDeletions(s: string): number {
  const n = s.length;
  let best = Infinity;
  for (let cut = 0; cut <= n; cut++) {
    let cost = 0;
    for (let i = 0; i < cut; i++) if (s[i] === "b") cost++;
    for (let i = cut; i < n; i++) if (s[i] === "a") cost++;
    best = Math.min(best, cost);
  }
  return best;
}

